#!/usr/bin/env node
// Rebuild the executor from the locked, reviewed Rust sources.
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { createRequire } from 'node:module';
import { execFileSync } from 'node:child_process';
import { createHash } from 'node:crypto';

const packageDir = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const repository = path.resolve(packageDir, '../..');
if (process.platform !== 'linux' || process.arch !== 'x64') {
  throw new Error('Canonical Wasm builds require Linux x86_64. Run misc/dependency_security/rebuild_wasm_in_container.sh --check (or --write to regenerate), or use the pinned Linux tools documented in misc/dependency_security/WASM-REBUILDS.md.');
}
const args = process.argv.slice(2);
const check = args.includes('--check');
const toolsIndex = args.indexOf('--build-tools-dir');
const toolsDir = toolsIndex >= 0 ? path.resolve(args[toolsIndex + 1]) : packageDir;
const requireTools = createRequire(path.join(toolsDir, 'package.json'));
const swc = requireTools('@swc/core');
const { zlibSync } = requireTools('fflate/node');
const fflateManifest = path.resolve(path.dirname(requireTools.resolve('fflate/node')), '../package.json');
if (JSON.parse(fs.readFileSync(fflateManifest, 'utf8')).version !== '0.8.2') {
  throw new Error('Build requires fflate 0.8.2');
}
if (requireTools('@swc/core/package.json').version !== '1.16.20') {
  throw new Error('Build requires @swc/core 1.16.20');
}
const bindgen = process.env.WASM_BINDGEN || 'wasm-bindgen';
if (execFileSync(bindgen, ['--version'], { encoding: 'utf8' }).trim() !== 'wasm-bindgen 0.2.129') {
  throw new Error('Build requires wasm-bindgen-cli 0.2.129');
}
const targetDir = path.resolve(process.env.CARGO_TARGET_DIR || path.join(repository, 'target'));
const cargoHome = path.resolve(process.env.CARGO_HOME || path.join(os.homedir(), '.cargo'));
const sysroot = execFileSync('rustc', ['+nightly-2026-10-23', '--print', 'sysroot'], { encoding: 'utf8' }).trim();
const rustcInfo = execFileSync('rustc', ['+nightly-2026-10-23', '--version', '--verbose'], { encoding: 'utf8' });
const rustcCommit = rustcInfo.match(/^commit-hash: (\S+)$/m)?.[1];
const rustcHost = rustcInfo.match(/^host: (\S+)$/m)?.[1];
if (rustcHost !== 'x86_64-unknown-linux-gnu' || rustcCommit !== '7189d39d9ce936881b8132c6addeaf3e295cd455') {
  throw new Error('Build requires pinned nightly-2026-10-23 for x86_64-unknown-linux-gnu. See misc/dependency_security/WASM-REBUILDS.md.');
}
const env = { ...process.env, CARGO_TARGET_DIR: targetDir,
  // Pin the effective release profile; parent Cargo configuration must not alter it.
  CARGO_PROFILE_RELEASE_OPT_LEVEL: 's', CARGO_PROFILE_RELEASE_LTO: 'thin',
  CARGO_PROFILE_RELEASE_CODEGEN_UNITS: '1', CARGO_PROFILE_RELEASE_DEBUG: '0',
  CARGO_PROFILE_RELEASE_DEBUG_ASSERTIONS: 'false', CARGO_PROFILE_RELEASE_OVERFLOW_CHECKS: 'false',
  CARGO_PROFILE_RELEASE_PANIC: 'abort', CARGO_PROFILE_RELEASE_INCREMENTAL: 'false',
  CARGO_PROFILE_RELEASE_STRIP: 'none',
  RUSTFLAGS: `--remap-path-prefix=${repository}=/source --remap-path-prefix=${cargoHome}=/cargo --remap-path-prefix=${sysroot}=/rust-toolchain --remap-path-prefix=${sysroot}/lib/rustlib/src/rust=/rustc/${rustcCommit}` };
// Do not let an inherited encoded-flags variable override the reproducible flags.
delete env.CARGO_ENCODED_RUSTFLAGS;
execFileSync('cargo', ['+nightly-2026-10-23', 'build', '--manifest-path',
  path.join(packageDir, 'Cargo.toml'), '--locked', '--release', '--target', 'wasm32-unknown-unknown'],
  { cwd: packageDir, env, stdio: 'inherit' });

const stage = fs.mkdtempSync(path.join(os.tmpdir(), 'sora-executor-package-'));
const digest = data => createHash('sha256').update(data).digest('hex');
try {
  const pkg = path.join(stage, 'pkg');
  execFileSync(bindgen, ['--target', 'web', '--typescript', '--out-dir', pkg,
    path.join(targetDir, 'wasm32-unknown-unknown/release/chopsticks_executor.wasm')],
    { cwd: packageDir, env, stdio: 'inherit' });
  const wasm = fs.readFileSync(path.join(pkg, 'chopsticks_executor_bg.wasm'));
  const compressed = Buffer.from(zlibSync(wasm, { level: 9 }));
  fs.writeFileSync(path.join(pkg, 'index.js'), `// Generated by scripts/build-reviewed.mjs; do not edit.\n`
    + `const LEN_IN = ${compressed.length};\nconst LEN_OUT = ${wasm.length};\nconst BYTES = '${compressed.toString('base64')}';\n`
    + `import { base64Decode, unzlibSync } from '@polkadot/wasm-util';\n`
    + `const WASM_BYTES = unzlibSync(base64Decode(BYTES, new Uint8Array(LEN_IN)), new Uint8Array(LEN_OUT));\n`
    + `import { initSync } from './chopsticks_executor.js';\n`
    + `initSync({ module: new WebAssembly.Module(WASM_BYTES) });\n`
    + `export * from './chopsticks_executor.js';\n`);
  // The public entry embeds the bytes. Keep the upstream empty asset placeholder.
  fs.writeFileSync(path.join(pkg, 'chopsticks_executor_bg.wasm'), Buffer.alloc(0));
  const assets = {};
  for (const [directory, moduleType] of [['esm', 'es6'], ['cjs', 'commonjs']]) {
    for (const name of fs.readdirSync(pkg).sort()) {
      let contents = fs.readFileSync(path.join(pkg, name));
      if (name.endsWith('.js')) {
        contents = Buffer.from(swc.transformSync(contents.toString(), {
          filename: name, jsc: { target: 'es2020' }, module: { type: moduleType },
        }).code);
      }
      assets[`dist/${directory}/${name}`] = contents;
    }
    assets[`dist/${directory}/index.d.ts`] = fs.readFileSync(path.join(pkg, 'chopsticks_executor.d.ts'));
    assets[`dist/${directory}/package.json`] = Buffer.from(JSON.stringify({ type: directory === 'esm' ? 'module' : 'commonjs' }) + '\n');
  }
  if (check) {
    for (const [name, bytes] of Object.entries(assets)) {
      if (!fs.readFileSync(path.join(packageDir, name)).equals(bytes)) {
        throw new Error(`Rebuilt artifact differs: ${name}`);
      }
    }
    console.log(`Rebuilt executor matches all ${Object.keys(assets).length} committed assets; Wasm SHA-256 ${digest(wasm)}`);
  } else {
    for (const [name, bytes] of Object.entries(assets)) {
      const dest = path.join(packageDir, name);
      fs.mkdirSync(path.dirname(dest), { recursive: true });
      fs.writeFileSync(dest, bytes);
    }
    const sources = {};
    function collect(directory) {
      for (const entry of fs.readdirSync(directory, { withFileTypes: true })) {
        const file = path.join(directory, entry.name);
        if (entry.isDirectory()) collect(file);
        else if (entry.name.endsWith('.rs')) sources[path.relative(packageDir, file)] = digest(fs.readFileSync(file));
      }
    }
    collect(path.join(packageDir, 'src'));
    collect(path.join(packageDir, 'smoldot/src'));
    collect(path.join(repository, 'vendor/sora-secp256k1-compat/src'));
    for (const name of ['Cargo.toml', 'Cargo.lock', 'adapter/Cargo.toml', 'package.json', 'smoldot/Cargo.toml',
      '../sora-secp256k1-compat/Cargo.toml', '../../rust-toolchain.toml', '../../misc/dependency_security/Dockerfile.wasm-rebuild',
      '../../misc/dependency_security/rebuild_wasm_in_container.sh', 'scripts/build-reviewed.mjs']) {
      sources[name] = digest(fs.readFileSync(path.join(packageDir, name)));
    }
    const provenance = {
      executor_commit: 'f6eab24db852e24c2c66e459600c3b9d68e2aa7b',
      smoldot_commit: 'd3006b601d2b10fc0002c3e8022954bd37f052c9',
      canonical_host: 'x86_64-unknown-linux-gnu', rustc_commit: rustcCommit,
      release_profile: { opt_level: 's', lto: 'thin', codegen_units: 1, panic: 'abort' },
      rust_toolchain: 'nightly-2026-10-23', wasm_bindgen: '0.2.129', swc: '1.16.20', fflate: '0.8.2',
      wasm_sha256: digest(wasm), wasm_bytes: wasm.length,
      sources, assets: Object.fromEntries(Object.entries(assets).map(([name, bytes]) => [name, digest(bytes)])),
    };
    fs.writeFileSync(path.join(packageDir, 'build-provenance.json'), JSON.stringify(provenance, null, 2) + '\n');
    console.log(`Built ${wasm.length}-byte executor Wasm; SHA-256 ${digest(wasm)}`);
  }
} finally {
  fs.rmSync(stage, { recursive: true, force: true });
}
